sys_script_include.script:
var ProjectMCPStoryServiceSNC = Class.create();

ProjectMCPStoryServiceSNC.prototype = {

    initialize: function() {
    },

    /**
     * Create a new Story.
     *
     * Supported input:
     *   short_description   required
     *   description
     *   acceptance_criteria
     *   project             project sys_id or project number
     *   sprint              sprint sys_id, number, or name
     *   story_points
     *   assigned_to         user sys_id, user_name, or email
     *   assignment_group    group sys_id or name
     *   priority
     *
     * @param {Object} input - Story fields
     * @returns {Object}
     */
    createStory: function(input) {
        if (!input || typeof input !== 'object') {
            return {
                success: false,
                status: 400,
                error: 'Missing request body'
            };
        }

        if (gs.nil(input.short_description) ||
            String(input.short_description).trim() === '') {

            return {
                success: false,
                status: 400,
                error: 'Missing required field: short_description'
            };
        }

        var story = new GlideRecordSecure('rm_story');

        if (!story.canCreate()) {
            return {
                success: false,
                status: 403,
                error: 'Not authorized to create stories'
            };
        }

        story.initialize();

        story.setValue(
            'short_description',
            String(input.short_description).trim()
        );

        if (this._isProvided(input.description)) {
            story.setValue('description', input.description);
        }

        if (this._isProvided(input.acceptance_criteria)) {
            story.setValue(
                'acceptance_criteria',
                input.acceptance_criteria
            );
        }

        /*
         * Resolve reference fields. These accept either a sys_id or
         * a useful human-readable identifier.
         */
        var result;

        result = this._setReferenceField(
            story,
            'project',
            input.project,
            ['number']
        );

        if (!result.success) {
            return result;
        }

        result = this._setReferenceField(
            story,
            'sprint',
            input.sprint,
            ['number', 'name']
        );

        if (!result.success) {
            return result;
        }

        result = this._setReferenceField(
            story,
            'assigned_to',
            input.assigned_to,
            ['user_name', 'email']
        );

        if (!result.success) {
            return result;
        }

        result = this._setReferenceField(
            story,
            'assignment_group',
            input.assignment_group,
            ['name']
        );

        if (!result.success) {
            return result;
        }

        /*
         * Story points must be numeric and non-negative.
         */
        if (this._isProvided(input.story_points)) {
            var points = parseFloat(input.story_points);

            if (isNaN(points) || points < 0) {
                return {
                    success: false,
                    status: 400,
                    error: 'story_points must be a non-negative number'
                };
            }

            story.setValue('story_points', points);
        }

        if (this._isProvided(input.priority)) {
            story.setValue('priority', input.priority);
        }

        var sysId = story.insert();

        if (gs.nil(sysId)) {
            return {
                success: false,
                status: 400,
                error: story.getLastErrorMessage() ||
                    'Story could not be created'
            };
        }

        /*
         * Re-query so generated values and Business Rule changes
         * are reflected in the response.
         */
        var createdStory = new GlideRecordSecure('rm_story');

        if (!createdStory.get(sysId)) {
            return {
                success: true,
                status: 201,
                data: {
                    sys_id: sysId
                }
            };
        }

        return {
            success: true,
            status: 201,
            data: {
                sys_id: createdStory.getUniqueValue(),
                number: this._value(createdStory, 'number'),
                short_description: this._value(
                    createdStory,
                    'short_description'
                ),
                description: this._value(
                    createdStory,
                    'description'
                ),
                acceptance_criteria: this._value(
                    createdStory,
                    'acceptance_criteria'
                ),

                state: this._valueAndDisplay(
                    createdStory,
                    'state'
                ),
                priority: this._valueAndDisplay(
                    createdStory,
                    'priority'
                ),

                points: this._number(
                    createdStory,
                    'story_points'
                ),

                project: this._reference(
                    createdStory,
                    'project'
                ),
                assignment_group: this._reference(
                    createdStory,
                    'assignment_group'
                ),
                assigned_to: this._reference(
                    createdStory,
                    'assigned_to'
                ),
                sprint: this._reference(
                    createdStory,
                    'sprint'
                ),

                sys_created_on: this._value(
                    createdStory,
                    'sys_created_on'
                )
            }
        };
    },

    /**
     * Returns stories associated with a project.
     *
     * @param {String} projectNumber - Project number, e.g. PRJ0010001
     * @param {Object} options - Optional paging settings
     * @returns {Object}
     */
    listForProject: function(projectNumber, options) {
        if (gs.nil(projectNumber)) {
            return {
                success: false,
                status: 400,
                error: 'Missing required parameter: project number'
            };
        }

        options = options || {};

        var limit = this._parseInteger(options.limit, 50, 1, 100);
        var offset = this._parseInteger(options.offset, 0, 0, 100000);

        /*
         * Resolve the project number to its sys_id first.
         */
        var project = new GlideRecordSecure('pm_project');
        project.addQuery('number', projectNumber);
        project.setLimit(1);
        project.query();

        if (!project.next()) {
            return {
                success: false,
                status: 404,
                error: 'Project not found: ' + projectNumber
            };
        }

        var projectSysId = project.getUniqueValue();

        /*
         * Request one additional record so we can determine whether
         * another page exists without running a separate count query.
         */
        var story = new GlideRecordSecure('rm_story');
        story.addQuery('project', projectSysId);
        story.orderBy('priority');
        story.orderBy('number');
        story.chooseWindow(offset, offset + limit + 1);
        story.query();

        var stories = [];

        while (story.next()) {
            stories.push(this._serializeStory(story));
        }

        var hasMore = stories.length > limit;

        if (hasMore) {
            stories.pop();
        }

        return {
            success: true,
            status: 200,
            data: {
                project: {
                    sys_id: projectSysId,
                    number: this._value(project, 'number'),
                    short_description: this._value(
                        project,
                        'short_description'
                    )
                },

                stories: stories,

                pagination: {
                    limit: limit,
                    offset: offset,
                    returned: stories.length,
                    has_more: hasMore,
                    next_offset: hasMore ? offset + limit : null
                }
            }
        };
    },

    /**
     * Returns detailed information for a single story.
     *
     * @param {String} number - Story number, e.g. STRY0010001
     * @returns {Object}
     */
    getByNumber: function(number) {
        if (gs.nil(number)) {
            return {
                success: false,
                status: 400,
                error: 'Missing required parameter: number'
            };
        }

        var story = new GlideRecordSecure('rm_story');
        story.addQuery('number', number);
        story.setLimit(1);
        story.query();

        if (!story.next()) {
            return {
                success: false,
                status: 404,
                error: 'Story not found: ' + number
            };
        }

        var data = {
            sys_id: story.getUniqueValue(),
            number: this._value(story, 'number'),
            short_description: this._value(
                story,
                'short_description'
            ),
            description: this._value(story, 'description'),
            acceptance_criteria: this._value(
                story,
                'acceptance_criteria'
            ),

            state: this._valueAndDisplay(story, 'state'),
            priority: this._valueAndDisplay(story, 'priority'),
            type: this._valueAndDisplay(story, 'type'),
            classification: this._valueAndDisplay(
                story,
                'classification'
            ),

            points: this._number(story, 'story_points'),
            blocked: this._boolean(story, 'blocked'),
            active: this._boolean(story, 'active'),

            project: this._reference(story, 'project'),
            project_phase: this._reference(
                story,
                'project_phase'
            ),

            assignment_group: this._reference(
                story,
                'assignment_group'
            ),
            assigned_to: this._reference(story, 'assigned_to'),
            sprint: this._reference(story, 'sprint'),

            epic: this._reference(story, 'epic'),
            product: this._reference(story, 'product'),
            release: this._reference(story, 'release'),

            sys_created_on: this._value(
                story,
                'sys_created_on'
            ),
            sys_updated_on: this._value(
                story,
                'sys_updated_on'
            )
        };

        /*
         * Some Story fields vary depending on installed plugins/version.
         */
        data.theme = this._reference(story, 'theme');
        data.demand = this._reference(story, 'demand');

        data.activity = {
            comments: this._latestJournalEntry(
                story,
                'comments'
            ),
            work_notes: this._latestJournalEntry(
                story,
                'work_notes'
            )
        };

        return {
            success: true,
            status: 200,
            data: data
        };
    },

    /**
     * Serialize a Story for list responses.
     */
    _serializeStory: function(story) {
        return {
            sys_id: story.getUniqueValue(),
            number: this._value(story, 'number'),
            short_description: this._value(
                story,
                'short_description'
            ),

            state: this._valueAndDisplay(story, 'state'),
            priority: this._valueAndDisplay(story, 'priority'),

            points: this._number(story, 'story_points'),
            blocked: this._boolean(story, 'blocked'),
            active: this._boolean(story, 'active'),

            assignment_group: this._reference(
                story,
                'assignment_group'
            ),
            assigned_to: this._reference(story, 'assigned_to'),
            sprint: this._reference(story, 'sprint'),

            epic: this._reference(story, 'epic'),
            product: this._reference(story, 'product'),
            release: this._reference(story, 'release'),
            project_phase: this._reference(
                story,
                'project_phase'
            ),

            sys_updated_on: this._value(
                story,
                'sys_updated_on'
            )
        };
    },

    /**
     * Set a reference field from either a sys_id or one of the
     * supplied lookup fields.
     */
    _setReferenceField: function(
        record,
        fieldName,
        inputValue,
        lookupFields
    ) {
        if (!this._isProvided(inputValue)) {
            return {
                success: true
            };
        }

        if (!record.isValidField(fieldName)) {
            return {
                success: false,
                status: 400,
                error: 'Field is not available: ' + fieldName
            };
        }

        var element = record.getElement(fieldName);
        var referenceTable = element.getReferenceTable();

        if (gs.nil(referenceTable)) {
            return {
                success: false,
                status: 400,
                error: fieldName + ' is not a reference field'
            };
        }

        var value = String(inputValue).trim();
        var reference = new GlideRecordSecure(referenceTable);

        /*
         * Check sys_id first.
         */
        if (reference.get(value)) {
            record.setValue(fieldName, reference.getUniqueValue());

            return {
                success: true
            };
        }

        /*
         * Otherwise search human-readable identifiers.
         */
        reference = new GlideRecordSecure(referenceTable);

        var query = null;

        for (var i = 0; i < lookupFields.length; i++) {
            var lookupField = lookupFields[i];

            if (!reference.isValidField(lookupField)) {
                continue;
            }

            if (query === null) {
                query = reference.addQuery(
                    lookupField,
                    value
                );
            } else {
                query.addOrCondition(
                    lookupField,
                    value
                );
            }
        }

        if (query === null) {
            return {
                success: false,
                status: 400,
                error: 'Unable to resolve reference field: ' +
                    fieldName
            };
        }

        /*
         * Retrieve at most two so ambiguous matches can be rejected.
         */
        reference.setLimit(2);
        reference.query();

        if (!reference.next()) {
            return {
                success: false,
                status: 404,
                error: 'No matching record found for ' +
                    fieldName + ': ' + value
            };
        }

        var sysId = reference.getUniqueValue();

        if (reference.next()) {
            return {
                success: false,
                status: 409,
                error: 'Multiple records matched ' +
                    fieldName + ': ' + value
            };
        }

        record.setValue(fieldName, sysId);

        return {
            success: true
        };
    },

    /**
     * Determine whether an optional input was actually supplied.
     */
    _isProvided: function(value) {
        return value !== undefined &&
            value !== null &&
            String(value).trim() !== '';
    },

    /**
     * Return a raw field value or null.
     */
    _value: function(gr, fieldName) {
        if (!gr || !gr.isValidField(fieldName)) {
            return null;
        }

        var value = gr.getValue(fieldName);

        return gs.nil(value) ? null : value;
    },

    /**
     * Return both the raw and display values for a field.
     */
    _valueAndDisplay: function(gr, fieldName) {
        if (!gr || !gr.isValidField(fieldName)) {
            return null;
        }

        var value = gr.getValue(fieldName);

        if (gs.nil(value)) {
            return null;
        }

        return {
            value: value,
            display_value: gr.getDisplayValue(fieldName)
        };
    },

    /**
     * Return a reference field as its sys_id and display value.
     */
    _reference: function(gr, fieldName) {
        if (!gr || !gr.isValidField(fieldName)) {
            return null;
        }

        var value = gr.getValue(fieldName);

        if (gs.nil(value)) {
            return null;
        }

        return {
            value: value,
            display_value: gr.getDisplayValue(fieldName)
        };
    },

    /**
     * Return a numeric field as a JavaScript number.
     */
    _number: function(gr, fieldName) {
        if (!gr || !gr.isValidField(fieldName)) {
            return null;
        }

        var value = gr.getValue(fieldName);

        if (gs.nil(value)) {
            return null;
        }

        var number = parseFloat(value);

        return isNaN(number) ? null : number;
    },

    /**
     * Return a Glide boolean field as a JavaScript boolean.
     */
    _boolean: function(gr, fieldName) {
        if (!gr || !gr.isValidField(fieldName)) {
            return null;
        }

        var value = gr.getValue(fieldName);

        if (gs.nil(value)) {
            return null;
        }

        return value == 'true' || value == '1';
    },

    /**
     * Return the most recent entry from a journal field.
     */
    _latestJournalEntry: function(gr, fieldName) {
        if (!gr || !gr.isValidField(fieldName)) {
            return null;
        }

        try {
            var value = gr.getElement(
                fieldName
            ).getJournalEntry(-1);

            return gs.nil(value) ? null : value;
        } catch (e) {
            return null;
        }
    },

    /**
     * Parse, default, and clamp an integer option.
     */
    _parseInteger: function(value, defaultValue, min, max) {
        var parsed = parseInt(value, 10);

        if (isNaN(parsed)) {
            parsed = defaultValue;
        }

        if (parsed < min) {
            parsed = min;
        }

        if (parsed > max) {
            parsed = max;
        }

        return parsed;
    },

    type: 'ProjectMCPStoryServiceSNC'
};
